using System.Reflection;
using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string Root = "PaymentAuthorization";

    private static readonly Assembly Domain = typeof(Domain.Money).Assembly;
    private static readonly Assembly Application = typeof(Application.IReceiptStore).Assembly;

    // Technical details that business code must reach only through ports.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    [Fact]
    public void Domain_depends_on_no_other_layer() =>
        AssertNoDependency(Domain, $"{Root}.Application", $"{Root}.Infrastructure");

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoDependency(Application, $"{Root}.Infrastructure");

    [Fact]
    public void Domain_does_not_use_technical_namespaces() =>
        AssertNoDependency(Domain, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_namespaces() =>
        AssertNoDependency(Application, TechnicalNamespaces);

    private static void AssertNoDependency(Assembly assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful,
            "Forbidden dependencies in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
